#!/usr/bin/env python3
# luxarch:statusline hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""The status line: how full the context window is, e.g. `[Opus] 73% context`.

Wired as `statusLine` in the repo's .claude/settings.json by the hooks installer. Claude Code hands it
the exact `context_window.used_percentage` and the `session_id` on stdin. It also records that
percentage for `context-watch`, which warns at 85% so there is time to run /wrap-up before
auto-compaction: no hook is told the context size, and a transcript does not record the window (200K
or 1M), so this is the one place the true value exists.

v2: a project `statusLine` overrides each developer's own, and the committed settings reach every
teammate. So when the user has their own (`~/.claude/settings.json`), it is run on the same input and
the percentage is appended to its line (`<theirs> · 73% context`): nobody's status line is replaced.

The record is `~/.claude/context-watch/<session_id>.json`, one file per session, written atomically;
files older than two days are removed on each write. Never fails the status line: any error still
prints a line and exits 0. Python 3.9, stdlib only.
"""

from __future__ import annotations

import contextlib
import json
import os
import select
import signal
import subprocess
import sys
import tempfile
import time
from pathlib import Path
from typing import IO

STATE_DIR = Path.home() / ".claude" / "context-watch"
# Claude Code reads the user's settings from CLAUDE_CONFIG_DIR when it is set, else ~/.claude
USER_SETTINGS = (
    Path(os.environ.get("CLAUDE_CONFIG_DIR") or Path.home() / ".claude")
    / "settings.json"
)
_KEEP_SECONDS = 2 * 24 * 3600
_NESTED = "LUXARCH_STATUSLINE_NESTED"

# named tuples, not `except (A, B):`: the 3.14 formatter rewrites that to `except A, B:`, which
# Python 3.9 (macOS, iOS repos) cannot parse
_BAD_INPUT = (ValueError, OSError, RecursionError)
_THEIRS_FAILED = (OSError, ValueError, subprocess.SubprocessError)


def _record(session: str, used: float) -> None:
    if not session or "/" in session or session.startswith(".") or "\0" in session:
        return
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=STATE_DIR, prefix=".tmp-")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(
                {"session_id": session, "used_percentage": used, "at": time.time()}, f
            )
        os.replace(tmp, STATE_DIR / f"{session}.json")
    finally:
        with contextlib.suppress(OSError):
            os.unlink(tmp)  # gone after a successful replace; an orphan otherwise
    cutoff = time.time() - _KEEP_SECONDS
    for p in STATE_DIR.iterdir():
        with contextlib.suppress(OSError):
            if p.stat().st_mtime < cutoff:
                p.unlink()


def _field(obj: object, key: str) -> object:
    return obj.get(key) if isinstance(obj, dict) else None


def _theirs(raw: str) -> str:
    """The user's own status line, run on the same input; "" when they have none (or it fails).

    Round 2 of the adversarial pass: a user's status line that is itself a wrapper calling ours
    recursed without end (700+ processes in 12s), so the child carries a marker and a nested call never
    runs theirs again. The command runs in its own session, only its first line is read (4 KB at most),
    and on timeout the whole process group is killed: a hanging command left orphans, and a flooding
    one (`yes`) grew this process past 1 GB."""
    if os.environ.get(_NESTED):
        return ""
    try:
        cmd = _field(
            json.loads(USER_SETTINGS.read_text(encoding="utf-8")), "statusLine"
        )
    except _BAD_INPUT:
        return ""
    command = _field(cmd, "command")
    if not isinstance(command, str) or not command.strip():
        return ""
    try:
        p = subprocess.Popen(
            [
                "/bin/sh",
                "-c",
                command,
            ],  # a statusLine is a shell command, as Claude Code runs it
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
            env={**os.environ, _NESTED: "1"},
        )
    except _THEIRS_FAILED:
        return ""
    first = b""
    try:
        if p.stdin is not None:
            with contextlib.suppress(OSError):
                p.stdin.write(raw.encode("utf-8", "replace"))
                p.stdin.close()
        deadline = time.monotonic() + 3
        while p.stdout is not None and b"\n" not in first and len(first) < 4096:
            if not _readable(p.stdout, deadline):
                break
            chunk = os.read(p.stdout.fileno(), 4096 - len(first))
            if not chunk:
                break
            first += chunk
    finally:
        with contextlib.suppress(OSError):
            os.killpg(p.pid, signal.SIGKILL)
        with contextlib.suppress(OSError, subprocess.SubprocessError):
            p.wait(timeout=1)
    return first.split(b"\n", 1)[0].decode("utf-8", "replace").rstrip()


def _readable(stream: IO[bytes], deadline: float) -> bool:
    wait = deadline - time.monotonic()
    if wait <= 0:
        return False
    ready, _, _ = select.select([stream], [], [], wait)
    return bool(ready)


def line(event: dict[str, object], raw: str = "") -> str:
    model = _field(event.get("model"), "display_name") or "Claude"
    used = _field(event.get("context_window"), "used_percentage")
    theirs = _theirs(raw) if raw else ""
    if not isinstance(used, (int, float)) or isinstance(used, bool):
        return theirs or f"[{model}]"
    with contextlib.suppress(OSError, ValueError):
        _record(str(event.get("session_id") or ""), float(used))
    ours = f"{int(used)}% context"
    return f"{theirs} · {ours}" if theirs else f"[{model}] {ours}"


def main() -> int:
    raw = ""
    try:
        raw = sys.stdin.read()
        event = json.loads(raw)
        text = line(event if isinstance(event, dict) else {}, raw)
    except _BAD_INPUT:
        text = "[Claude]"
    with contextlib.suppress(OSError):
        sys.stdout.write(text + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
